WITH base AS (SELECT * FROM departments WHERE location NOT IN ('Bangkok', 'Tokyo', 'Berlin') OR dept_name = 'Marketing'), location_summary AS (SELECT location, CASE WHEN budget >= 3890000 THEN 'high' WHEN budget >= 1349000 THEN 'mid' ELSE 'low' END AS budget_bucket, SUM(budget) AS total_budget, ROUND((100 * SUM(CASE WHEN dept_name = 'Finance' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_finance FROM base GROUP BY location, CASE WHEN budget >= 3890000 THEN 'high' WHEN budget >= 1349000 THEN 'mid' ELSE 'low' END) SELECT * FROM location_summary ORDER BY total_budget DESC
